<script setup lang="ts">
import {computed,ref} from 'vue'
import {useRouter} from 'vue-router'
import {ArrowUpRight,ShieldCheck,Leaf} from 'lucide-vue-next'
import {session,post,localDateTime} from '../api'
const router=useRouter(),orgs=computed(()=>session.organizations.filter(o=>o.kind==='donor'&&o.status==='approved'))
const soon=new Date(Date.now()+3600000),later=new Date(Date.now()+10800000),expire=new Date(Date.now()+14400000)
const form=ref({organization_id:'',title:'',category:'bakery',quantity:1,unit:'portions',weight_kg:1,area:'',pickup_address:'',contact:'',storage_notes:'',allergens:'',pickup_start:localDateTime(soon.toISOString()),pickup_end:localDateTime(later.toISOString()),expires_at:localDateTime(expire.toISOString()),safety_acknowledged:false})
const busy=ref(false),error=ref('');let key=crypto.randomUUID()
async function submit(){if(busy.value)return;busy.value=true;error.value='';try{const body={...form.value,organization_id:form.value.organization_id||orgs.value[0]?.id,pickup_start:new Date(form.value.pickup_start).toISOString(),pickup_end:new Date(form.value.pickup_end).toISOString(),expires_at:new Date(form.value.expires_at).toISOString()};const r=await post<{id:string}>('/batches',body,key);key=crypto.randomUUID();router.push(`/batches/${r.id}`)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><section class="container page-section"><div class="page-heading"><div class="eyebrow">SHARE SOMETHING GOOD</div><h1>给好食物，一个新去处。</h1><p>填写真实的食品信息，方便社区组织安排领取。</p></div><div v-if="!session.loaded" class="empty-state">正在确认账户…</div><div v-else-if="!session.user" class="empty-state"><Leaf :size="36"/><h3>先加入我们的社区</h3><p>请登录或创建商家组织，审核通过后即可发布食品。</p><RouterLink class="button" to="/login">去登录</RouterLink></div><div v-else-if="!orgs.length" class="empty-state"><ShieldCheck :size="36"/><h3>发布需要已审核的商家身份</h3><p>新组织正在等待运营人员审核。社区接收方可以在首页认领食品。</p><RouterLink class="button" to="/workspace">查看组织状态</RouterLink></div><div v-else class="form-layout"><form class="surface batch-form" @submit.prevent="submit"><h2>食品基本信息</h2><label v-if="orgs.length>1">发布组织<select v-model="form.organization_id" required><option disabled value="">选择组织</option><option v-for="o in orgs" :key="o.id" :value="o.id">{{o.name}}</option></select></label><label>食品名称<input v-model="form.title" required maxlength="160" placeholder="例如：今日余量全麦面包"/></label><div class="form-grid"><label>食品类别<select v-model="form.category"><option value="bakery">烘焙食品</option><option value="produce">新鲜果蔬</option><option value="packaged">包装食品</option><option value="prepared">即食餐食</option></select></label><label>所在地区<input v-model="form.area" required maxlength="100" placeholder="例如：Bencoolen"/></label></div><div class="form-grid three"><label>数量<input v-model.number="form.quantity" type="number" min="1" max="100000" required/></label><label>单位<select v-model="form.unit"><option value="portions">份</option><option value="items">件</option><option value="boxes">箱</option></select></label><label>预计重量 (kg)<input v-model.number="form.weight_kg" type="number" min="0.001" max="100000" step="0.001" required/></label></div><h2>领取安排</h2><div class="form-grid"><label>开始领取<input v-model="form.pickup_start" type="datetime-local" required/></label><label>领取截止<input v-model="form.pickup_end" type="datetime-local" required/></label></div><label>食品到期时间<input v-model="form.expires_at" type="datetime-local" required/></label><p class="form-hint">使用你浏览器的本地时区。领取截止必须晚于开始且不晚于到期时间。</p><label>详细取货地址<input v-model="form.pickup_address" maxlength="500" required placeholder="仅发布方及认领成功的组织可见"/></label><label>交接联系人 / 电话<input v-model="form.contact" maxlength="200" required placeholder="仅发布方及认领成功的组织可见"/></label><h2>安全与储存</h2><label>保存与运输要求<textarea v-model="form.storage_notes" maxlength="1000" required placeholder="保存温度、包装状态、运输要求等"></textarea></label><label>过敏原及成分说明<textarea v-model="form.allergens" maxlength="500" required placeholder="例如：含小麦、牛奶；不确定的成分请如实说明"></textarea></label><label class="checkbox"><input v-model="form.safety_acknowledged" type="checkbox" required/>我确认所填信息真实，并由发布组织负责确认食品适合捐赠、妥善保存及安全交接。</label><p v-if="error" class="error" role="alert">{{error}}</p><button class="button" :disabled="busy">{{busy?'发布中…':'发布食品余量'}}<ArrowUpRight :size="17"/></button></form><aside class="form-aside"><ShieldCheck :size="32"/><h3>让善意，也让安心同行。</h3><p>发布前请确认食品仍适合食用，并为领取组织留出足够的运输时间。</p><ul><li>如实填写过敏原与保存要求</li><li>只发布可安全交接的食品</li><li>在约定时段内完成交接</li><li>二维码只用于交接确认</li></ul><small>记录核验无法替代食品安全检查。</small></aside></div></section></template>
